argv:
$ErrorActionPreference='Continue'
$o=[ordered]@{at=(Get-Date).ToUniversalTime().ToString('o')}
$ps=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" -ErrorAction SilentlyContinue)
$o.chromeCount=$ps.Count
$o.chromeRoots=@($ps|Where-Object{$_.CommandLine -match '--user-data-dir=|--remote-debugging-port=|--proxy-(server|pac-url|bypass-list)|--no-proxy-server'}|ForEach-Object{
 $a=$_.CommandLine
 $p=[regex]::Match($a,'--remote-debugging-port(?:=|\s+)(\d+)')
 $d=[regex]::Match($a,'--user-data-dir(?:=|\s+)(?:"([^"]+)"|([^\s]+))')
 $q=[regex]::Match($a,'--proxy-server(?:=|\s+)(?:"([^"]+)"|([^\s]+))')
 [ordered]@{pid=$_.ProcessId;parentPid=$_.ParentProcessId;debugPort=if($p.Success){$p.Groups[1].Value}else{''};userDataDir=if($d.Success){if($d.Groups[1].Success){$d.Groups[1].Value}else{$d.Groups[2].Value}}else{''};proxyServerFlagPresent=$q.Success;proxyPacFlagPresent=($a -match '--proxy-pac-url');proxyBypassFlagPresent=($a -match '--proxy-bypass-list');noProxyServerFlagPresent=($a -match '--no-proxy-server')}
})
$o.osProxy=[ordered]@{}
try{$r=Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' -ErrorAction Stop;$o.osProxy.proxyEnable=[int]$r.ProxyEnable;$o.osProxy.autoConfigUrlPresent=![string]::IsNullOrWhiteSpace([string]$r.AutoConfigURL);$o.osProxy.proxyServerConfigured=![string]::IsNullOrWhiteSpace([string]$r.ProxyServer)}catch{$o.osProxy.state='unknown'}
foreach($port in @(17410,17447)){try{$r=Invoke-RestMethod -Uri ('http://127.0.0.1:'+ $port+'/json/version') -TimeoutSec 2;$o['cdp'+$port]=[ordered]@{available=$true;browser=$r.Browser}}catch{$o['cdp'+$port]=[ordered]@{available=$false}}}
$o|ConvertTo-Json -Compress -Depth 6
